using System.Linq;
using static StrataLint.Scribe.DefinitionDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry.Hyperideal;

internal sealed class FlatComponentBudgetDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Geometry/Hyperideal/FlatComponentBudget.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Native logarithmic budgets, saturated actual quotient support and genuine endpoints.",
        H("Actual flat face components"), Blocks(
            Paragraph(Text("T is any finite tetrahedron type and p:EdgeStarTransitions.RawFacePairing(T) is one actual whole-face pairing. Occ=T times Fin(6), E=p.GlobalEdge is exactly the quotient by the equivalence relation generated by p.edgeStep, and P(t,q)=p.edgeLabel(t,q). The local order is (12,13,14,34,24,23), with opposite pairs (0,3),(1,4),(2,5). No coloring, face normal orientation, injectivity of local labels or exclusion of self-gluing is assumed. In the original source, p is the fixed ideal triangulation of the compact connected orientable 3-manifold with nonempty boundary of genus at least two. The conclusions here hold for every finite raw pairing, so no additional manifold property is used.")),
            Paragraph(Text("One function ell:E->Real supplies all block coordinates x(t,q)=cosh(ell(P(t,q))) and angles alpha(t,q)=TwoLengthAngleSum.extendedAngle(x(t),q). Flat(t) means that x(t) is in one of the three closed native sectors from PositiveFlatClassification.positive_classification. Thus F=flats(p,ell) is derived from the original formula, with its unique opposite pi pair and four zero angles. Outside F every angle is strictly between zero and pi when ell is positive. The source global angle equation AngleSums is sum over all occurrences in each P fiber equals 2*pi. Degree d(e) is the full fiber cardinality.")),
            Paragraph(Text("For any finite C subset T, n(C,e) counts all occurrences with block in C and global label e; m(C,e) counts those same occurrences whose actual angle is pi. Repeated labels retain their multiplicity. FaceStep(t,u) means both blocks are flat and some actual p.facePair sends a face of t to a face of u. SameFlatComponent includes flatness at both ends and the generated equivalence relation. component(t) is its finite class. These face components are not defined using the pi graph.")),
            Paragraph(Text("RestrictedFlatEdgeChain(p,ell,i,j) abbreviates EqvGen of the relation p.edgeStep(u,v) together with Flat(p,ell,u.fst) and Flat(p,ell,v.fst), from i to j. Endpoint(p,ell,C,e) means that some occurrence i has i.fst in C, P(i)=e and alpha(i)=pi, that the global m(F,e)=1, and that some occurrence j has P(j)=e with j.fst outside Flat. The classifier makes that last block genuine. All weighted coefficients and cardinalities in real sums use their real casts.")),
            Paragraph(Text("The information-escape audits for m_le_two, saturated_support, native_component_budget, genuine_of_single_pi, component_exposed_label and component_endpoints remain unfinished under https://github.com/the-omega-institute/trureturing/issues/17994. The universal native_component_budget family has compiled proof evidence, but its source registration remains blocked by the rigid-universe decoder. The other five audits lack complete variation, sensitivity, observational-dependence and admissible source-selection evidence. The issue supplies neither mathematical proof nor validated registration status.")),
            Node("pi-multiplicity", "At most two flat pi contributions", "m_le_two", Multiplicity(),
                "Nonnegative native angles and the actual global 2*pi sum bound the sum on the pi occurrence subset. That subset sum is exactly m(C,e)*pi."),
            Node("saturated-support", "Saturation restricts actual quotient support", "saturated_support", Support(),
                "If the global flat pi multiplicity is two, these two pi contributions exhaust the actual 2*pi sum. A genuine occurrence would contribute a strictly positive angle, so every occurrence in the entire quotient fiber is flat. Equality in the actual quotient supplies an EqvGen edgeStep chain. Induction retains its common global label, hence every intermediate block is flat. Projecting each paired-face edge step gives the actual flat face chain. This derives restricted support; it is not a saturation certificate premise."),
            Node("native-component-budget", "Native budget on every nonempty flat subset", "native_component_budget", Budget(),
                "Set w(e)=log(cosh(ell(e))) and h(e)=log(cosh(ell(e))/(cosh(ell(e))-1)). Sum PositiveFlatClassification.native_flat_budget after the actual six-slot frame permutation on each block in C. Fiberwise finite sum regrouping gives the coefficient 3*m(C,e)-n(C,e) and retains both positive pi correction contributions per block. The inequality is strict above card(C)*log(16). No supplied local or component budget is used."),
            Node("genuine-single-pi", "A single flat pi label touches a genuine block", "genuine_of_single_pi", Genuine(),
                "If every occurrence were flat, the native pi/zero classification would make the global angle sum exactly one*pi. This contradicts 2*pi. The occurrence outside Flat is genuine by the full positive-domain classifier."),
            Node("component-exposed-label", "One coefficient witness in each actual component", "component_exposed_label", Exposed(),
                "The strictly positive component budget gives a positive coefficient. If its global m were two, saturated support would put the entire fiber in this actual component, giving n=d>=6 and coefficient 3*2-d<=0. Hence its global and local m are one, and its local n is at most two. The single-pi result gives a genuine occurrence. The n<=2 assertion concerns this coefficient witness only."),
            Node("component-endpoints", "Two distinct globally single pi labels per component", "component_endpoints", Endpoints(),
                "Every flat block contributes precisely two pi occurrences. In a component, sum_e m(C,e)=2*card(C). Saturated support shows that any local m=1 is globally one. Splitting local multiplicities into zero, one and two makes the number of labels with local m=1 even. The coefficient witness makes this number positive, hence at least two. Both labels have actual pi occurrences in C and genuine occurrences globally. No n<=2 claim is made for both labels, and this parity argument does not assert that all pi graph components are paths."))));

    private static DocumentBlock Node(string id,string title,string decl,Formula statement,string prose)=>
        Describe.Lean(DescribeId.Create(id),DeclarationHandle.Create(Prefix+decl),H(title),
            StatementSource.FromAuthor(F.Disp(statement)),AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text(prose))),DescribeRole.Theorem);
    private static Formula T=>F.Id("T");
    private static Formula P=>F.Id("p");
    private static Formula E=>Call("GlobalEdge",P);
    private static Formula Ell=>F.Id("ell");
    private static Formula C=>F.Id("C");
    private static Formula Q=>Call("Fin",F.D(6));
    private static Formula Occ=>Call("Product",T,Q);
    private static Formula Flat(Formula t)=>Call("Flat",P,Ell,t);
    private static Formula M(Formula c,Formula e)=>Call("m",P,Ell,c,e);
    private static Formula N(Formula c,Formula e)=>Call("n",P,Ell,c,e);
    private static Formula Flats=>Call("flats",P,Ell);
    private static Formula Positive=>All([("e",E)],Lt(F.D(0),Call("value",Ell,F.Id("e"))));
    private static Formula Sums=>Call("AngleSums",P,Ell);
    private static Formula Degrees=>All([("e",E)],Le(F.D(6),Call("degree",P,F.Id("e"))));
    private static Formula Comp(Formula t)=>Call("component",P,Ell,t);
    private static Formula Base((string,Formula)[] extra,Formula body)=>All([
        ("T",F.Id("Type"))],F.Seq(F.OpenBracket,Call("Fintype",T),F.CloseBracket,F.Comma,F.Sp,
        All([("p",Call("RawFacePairing",T)),
        ("ell",Call("Function",E,F.Id("Real"))),..extra],body)));
    private static Formula Multiplicity()=>Base([("C",Call("Finset",T)),("e",E)],
        Imp(Sums,Le(M(C,F.Id("e")),F.D(2))));
    private static Formula Support()
    {
        var e=F.Id("e");var i=F.Id("i");var j=F.Id("j");
        return Base([("e",E),("i",Occ),("j",Occ)],Imp(And(Positive,Sums,Eq(M(Flats,e),F.D(2)),
            Eq(Call("label",P,i),e),Eq(Call("label",P,j),e)),
            And(Call("RestrictedFlatEdgeChain",P,Ell,i,j),Call("SameFlatComponent",P,Ell,Call("fst",i),Call("fst",j)))));
    }
    private static Formula Budget()
    {
        var e=F.Id("e");var baseTerm=Mul(Call("card",C),Call("log",F.D(1,6)));
        var weighted=Sum("e",E,Mul(Sub(Mul(F.D(3),M(C,e)),N(C,e)),Call("weight",P,Ell,e)));
        var corrections=Sum("e",E,Mul(M(C,e),Call("correction",P,Ell,e)));
        return Base([("C",Call("Finset",T))],Imp(And(Positive,
            All([("t",T)],Imp(Call("member",F.Id("t"),C),Flat(F.Id("t")))),Call("Nonempty",C)),
            And(Le(Add(baseTerm,Mul(F.D(2),corrections)),weighted),Lt(baseTerm,weighted))));
    }
    private static Formula GenuineWitness(Formula e)=>Exists("i",Occ,And(
        Eq(Call("label",P,F.Id("i")),e),Not(Flat(Call("fst",F.Id("i"))))));
    private static Formula Genuine()=>Base([("e",E)],Imp(And(Positive,Sums,Eq(M(Flats,F.Id("e")),F.D(1))),GenuineWitness(F.Id("e"))));
    private static Formula Exposed()
    {
        var t=F.Id("t");var e=F.Id("e");
        return Base([("t",T)],Imp(And(Positive,Sums,Degrees,Flat(t)),Exists("e",E,
            And(Eq(M(Flats,e),F.D(1)),Eq(M(Comp(t),e),F.D(1)),Le(N(Comp(t),e),F.D(2)),GenuineWitness(e)))));
    }
    private static Formula Endpoints()
    {
        var t=F.Id("t");var a=F.Id("a");var b=F.Id("b");
        return Base([("t",T)],Imp(And(Positive,Sums,Degrees,Flat(t)),Exists("a",E,Exists("b",E,
            And(Ne(a,b),Call("Endpoint",P,Ell,Comp(t),a),Call("Endpoint",P,Ell,Comp(t),b))))));
    }
    private static Formula Sum(string n,Formula t,Formula b)=>F.Seq(
        new Formula.Subscript(F.Sum,new Formula.Relation(F.Id(n),FormulaRelationOperator.MemberOf,t)),b);
    private static Formula All((string Name,Formula Type)[] v,Formula b)=>new Formula.BindMany(FormulaQuantifier.ForAll,[..v.Select(t=>new Formula.BoundVariable(FormulaIdentifier.Create(t.Name),t.Type))],b);
    private static Formula Exists(string n,Formula t,Formula b)=>new Formula.BindMany(FormulaQuantifier.Exists,[new Formula.BoundVariable(FormulaIdentifier.Create(n),t)],b);
    private static Formula Call(string n,params Formula[] a)=>new Formula.Apply(F.Id(n),[..a]);
    private static Formula And(params Formula[] a)=>a.Aggregate((x,y)=>new Formula.Logic(x,FormulaLogicOperator.And,y));
    private static Formula Not(Formula a)=>new Formula.Not(a);
    private static Formula Imp(Formula a,Formula b)=>new Formula.Logic(a,FormulaLogicOperator.Implies,b);
    private static Formula Eq(Formula a,Formula b)=>new Formula.Relation(a,FormulaRelationOperator.Equal,b);
    private static Formula Ne(Formula a,Formula b)=>new Formula.Relation(a,FormulaRelationOperator.NotEqual,b);
    private static Formula Lt(Formula a,Formula b)=>new Formula.Relation(a,FormulaRelationOperator.LessThan,b);
    private static Formula Le(Formula a,Formula b)=>new Formula.Relation(a,FormulaRelationOperator.LessThanOrEqual,b);
    private static Formula Add(Formula a,Formula b)=>new Formula.Binary(a,FormulaBinaryOperator.Add,b);
    private static Formula Sub(Formula a,Formula b)=>new Formula.Binary(a,FormulaBinaryOperator.Subtract,b);
    private static Formula Mul(Formula a,Formula b)=>new Formula.Binary(a,FormulaBinaryOperator.Multiply,b);
}
